using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed partial class StateQ {public List<PlanetColonyQ> Colonies{get;set;}=[];public List<PlanetLaunchQ> Launches{get;set;}=[];}
public sealed class PlanetColonyQ {public string Id{get;set;}=Guid.NewGuid().ToString("N");public string Planet{get;set;}="";public string System{get;set;}="";public string Owner{get;set;}="player";public int Level{get;set;}public bool Active{get;set;}=true;public DateTime Last{get;set;}public List<PlanetPinQ> Pins{get;set;}=[];public List<PlanetLinkQ> Links{get;set;}=[];public List<PlanetRouteQ> Routes{get;set;}=[];public Dictionary<string,decimal> Deposits{get;set;}=[];}
public sealed class PlanetPinQ {public string Id{get;set;}=Guid.NewGuid().ToString("N");public string Kind{get;set;}="Storage";public float X{get;set;}public float Y{get;set;}public int Heads{get;set;}=1;public int Resource{get;set;}public int Schematic{get;set;}public DateTime Due{get;set;}public Dictionary<string,decimal> Stock{get;set;}=[];public Dictionary<string,decimal> Pending{get;set;}=[];public bool Active{get;set;}=true;public string Status{get;set;}="Idle";public decimal Capacity=>Kind=="Launchpad"?10000:Kind=="Storage"?12000:5000;public int Cpu=>Kind=="Extractor"?300+Heads*20:Kind=="Processor"?200:Kind=="Launchpad"?360:50;public int Power=>Kind=="Extractor"?400+Heads*40:Kind=="Processor"?600:Kind=="Launchpad"?700:500;}
public sealed class PlanetLinkQ {public string A{get;set;}="";public string B{get;set;}="";public int Level{get;set;}public decimal Capacity=>1000*(1<<Level);public decimal Used{get;set;}}
public sealed class PlanetRouteQ {public string From{get;set;}="";public string To{get;set;}="";public string Item{get;set;}="";public decimal Rate{get;set;}=1000;}
public sealed class PlanetLaunchQ {public string Id{get;set;}=Guid.NewGuid().ToString("N");public string Colony{get;set;}="";public string System{get;set;}="";public SpacePosition Anchor{get;set;}public DateTime Expires{get;set;}public Dictionary<string,float> Items{get;set;}=[];public bool Consumed{get;set;}}
public sealed partial class DemoWorld {
 public decimal PinVolumeQ(PlanetPinQ p)=>p.Stock.Sum(i=>i.Value*(decimal)ItemVolume(i.Key));
 public string DeployColonyQ(string planet){var c=SolarCatalog.ById.GetValueOrDefault(planet);if(c?.Kind!=CelestialKind.Planet||c.System!=SystemId||Commander.Capsule||SystemsQ.Colonies.Any(p=>p.Planet==planet&&p.Active)||SystemsQ.Colonies.Count(p=>p.Active)>=1+IndustryLevel("Interplanetary Consolidation")||Balance<1000)return "Local planet, colony skill capacity and 1,000 CR required.";WalletChange(-1000,"Planetary command centre");var colony=new PlanetColonyQ{Planet=planet,System=SystemId,Last=Now};foreach(int id in CatalogQ.PiRaw)colony.Deposits[CatalogQ.Item(id)]=100000;colony.Pins.Add(new(){Kind="Command",X=.5f,Y=.5f,Due=Now});SystemsQ.Colonies.Add(colony);return "";}
 public string UpgradeColonyQ(string id){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==id&&c.Active);if(c==null||c.Owner!="player"||c.Level>=Math.Min(5,IndustryLevel("Command Center Upgrades"))||Balance<500)return "Owned colony, command-centre upgrade skill and 500 CR required.";WalletChange(-500,"Planetary command upgrade");c.Level++;return "";}
 public string PlacePinQ(string colony,string kind,float x,float y){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);if(c==null||c.Owner!="player"||kind is not("Extractor" or "Processor" or "Storage" or "Launchpad")||!float.IsFinite(x+y)||x<0||x>1||y<0||y>1||c.Pins.Count>=40)return "Owned active colony and a valid surface placement required.";var pin=new PlanetPinQ{Kind=kind,X=x,Y=y,Due=Now.AddHours(1)};if(c.Pins.Any(p=>Math.Abs(p.X-x)+Math.Abs(p.Y-y)<.04)||c.Pins.Sum(p=>p.Cpu)+pin.Cpu>1500+c.Level*800||c.Pins.Sum(p=>p.Power)+pin.Power>5000+c.Level*2500||Balance<100)return "Surface collision, CPU/power limit or insufficient construction credits.";WalletChange(-100,"Planetary pin construction");c.Pins.Add(pin);return "";}
 public string ConfigurePinQ(string colony,string pin,int source,int heads=1){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);var p=c?.Pins.FirstOrDefault(p=>p.Id==pin);if(p==null||c!.Owner!="player"||p.Pending.Count>0||heads<1||heads>10)return "Owned idle pin and one to ten extractor heads required.";if(p.Kind=="Extractor"){if(!CatalogQ.PiRaw.Contains(source))return "Choose a raw planetary resource.";int beforeCpu=p.Cpu,beforePower=p.Power,old=p.Heads;p.Heads=heads;if(c.Pins.Sum(p=>p.Cpu)>1500+c.Level*800||c.Pins.Sum(p=>p.Power)>5000+c.Level*2500){p.Heads=old;return "Extractor heads exceed command resources.";}p.Resource=source;p.Due=Now.AddHours(1);}
  else if(p.Kind=="Processor"){if(!CatalogQ.Data.Schematics.Any(s=>s.Id==source))return "Unknown source schematic.";var scheme=CatalogQ.Data.Schematics.First(s=>s.Id==source);var body=SolarCatalog.ById.GetValueOrDefault(c.Planet);if(scheme.PinKind=="High-Tech"&&body!=null&&!scheme.Planets.Any(t=>body.Type.Contains(t,StringComparison.OrdinalIgnoreCase)))return "This source high-tech schematic is restricted to its planet types.";p.Schematic=source;p.Due=default;}else return "Choose an extractor or processor.";return "";}
 public string LinkPinsQ(string colony,string a,string b,int level=0){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);if(c==null||c.Owner!="player"||a==b||level<0||level>5||!c.Pins.Any(p=>p.Id==a)||!c.Pins.Any(p=>p.Id==b)||Balance<50)return "Two owned distinct pins, link level and 50 CR required.";var link=c.Links.FirstOrDefault(l=>l.A==a&&l.B==b||l.A==b&&l.B==a);if(link==null)c.Links.Add(new(){A=a,B=b,Level=level});else link.Level=level;WalletChange(-50,"Planetary link capacity");return "";}
 public string RoutePinsQ(string colony,string from,string to,int type,decimal rate=1000){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);string item=CatalogQ.Item(type);if(c==null||c.Owner!="player"||rate<=0||rate>100000||!c.Links.Any(l=>l.A==from&&l.B==to||l.A==to&&l.B==from)||!CatalogQ.PiInputs.Contains(type)&&!CatalogQ.PiOutputs.Contains(type))return "Owned linked pins and planetary commodity route required.";var dest=c.Pins.First(p=>p.Id==to);if(dest.Kind=="Processor"&&!CatalogQ.Data.Schematics.Any(s=>s.Id==dest.Schematic&&s.Inputs.Any(i=>i.Type==type)))return "The destination schematic does not use this commodity.";c.Routes.RemoveAll(r=>r.From==from&&r.To==to&&r.Item==item);c.Routes.Add(new(){From=from,To=to,Item=item,Rate=rate});return "";}
 public string RemovePinQ(string colony,string pin){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);var p=c?.Pins.FirstOrDefault(p=>p.Id==pin);if(p==null||p.Kind=="Command"||p.Pending.Count>0||p.Stock.Values.Any(v=>v>0))return "Empty idle owned pin required; command centres use decommission.";c!.Pins.Remove(p);c.Links.RemoveAll(l=>l.A==pin||l.B==pin);c.Routes.RemoveAll(r=>r.From==pin||r.To==pin);return "";}
 public string ImportPlanetQ(string colony,string pin,int type,int quantity){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);var p=c?.Pins.FirstOrDefault(p=>p.Id==pin&&p.Kind=="Launchpad");var planet=c==null?null:SolarCatalog.ById.GetValueOrDefault(c.Planet);string item=CatalogQ.Item(type);if(c==null||c.Owner!="player"||p==null||planet==null||Docked||SystemId!=c.System||(SystemPosition-planet.WarpPosition).Length>2500||quantity<=0||ItemCount(item,false)<quantity||PinVolumeQ(p)+quantity*(decimal)ItemVolume(item)>p.Capacity)return "Approach the owned planet's orbital point with actual cargo and launchpad space.";decimal tax=quantity*ItemCatalog.Get(item).Price*.05m;if(Balance<tax)return "Customs import wallet too small.";WalletChange(-tax,"Planetary customs import");ChangeStack(item,false,-quantity);p.Stock[item]=p.Stock.GetValueOrDefault(item)+quantity;return "";}
 public string ExportPlanetQ(string colony,string pin,int type,int quantity){TickPlanetaryQ();var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==colony&&c.Active);var p=c?.Pins.FirstOrDefault(p=>p.Id==pin&&p.Kind is "Launchpad" or "Command");var planet=c==null?null:SolarCatalog.ById.GetValueOrDefault(c.Planet);string item=CatalogQ.Item(type);if(c==null||c.Owner!="player"||p==null||planet==null||quantity<=0||p.Stock.GetValueOrDefault(item)<quantity)return "Owned launchpad/command inventory and positive output quantity required.";decimal tax=quantity*ItemCatalog.Get(item).Price*.1m;if(Balance<tax)return "Customs export wallet too small.";WalletChange(-tax,"Planetary customs export");p.Stock[item]-=quantity;var launch=new PlanetLaunchQ{Colony=c.Id,System=c.System,Anchor=planet.WarpPosition,Expires=Now.AddDays(5),Items=new(){{item,quantity}}};SystemsQ.Launches.Add(launch);Bookmarks.Add(new("pi-q:"+launch.Id,c.System,"Planetary launch / "+planet.Name,launch.Anchor));BindPlanetLaunchesQ();return "";}
 public void BindPlanetLaunchesQ(){if(Docked)return;foreach(var l in SystemsQ.Launches.Where(l=>!l.Consumed&&l.Expires>Now&&l.System==SystemId&&SolarCatalog.GridKey(l.System,l.Anchor)==SolarGridKey))if(!Targets.Any(t=>t.Id=="pi-q:"+l.Id))Targets.Add(new(){Id="pi-q:"+l.Id,Name="Owned planetary launch",Kind=TargetKind.Container,Position=(l.Anchor-SolarOrigin).Local,OwnerId="player",Contents=l.Items,Signature=100});}
 public void TickPlanetaryQ(){foreach(var l in SystemsQ.Launches.Where(l=>!l.Consumed)){if(l.Expires<=Now){l.Items.Clear();l.Consumed=true;Targets.RemoveAll(t=>t.Id=="pi-q:"+l.Id);}else if(l.Items.Values.All(v=>v<=0))l.Consumed=true;}
  foreach(var c in SystemsQ.Colonies.Where(c=>c.Active)){long cycles=(long)Math.Floor(Math.Max(0,(Now-c.Last).TotalMinutes/30));if(cycles==0)continue;long bounded=Math.Min(cycles,720);for(long n=0;n<bounded;n++){DateTime at=c.Last.AddMinutes((n+1)*30);foreach(var l in c.Links)l.Used=0;
   foreach(var p in c.Pins.Where(p=>p.Active)){if(p.Kind=="Extractor"&&p.Resource>0&&p.Due<=at){string item=CatalogQ.Item(p.Resource);decimal density=(decimal)(.5+.5*Math.Abs(Math.Sin(p.X*13+p.Y*17+(StableC(c.Planet)%100)/10d)));decimal q=Math.Min(c.Deposits.GetValueOrDefault(item),Math.Min(decimal.Floor(3000*p.Heads*density),decimal.Floor((p.Capacity-PinVolumeQ(p))/(decimal)ItemVolume(item))));if(q>0){c.Deposits[item]-=q;p.Stock[item]=p.Stock.GetValueOrDefault(item)+q;p.Status="Extracting";}else p.Status=c.Deposits.GetValueOrDefault(item)==0?"Deposit exhausted":"Storage full";p.Due=at.AddHours(1);}
    if(p.Kind=="Processor"&&p.Schematic>0){var s=CatalogQ.Data.Schematics.First(s=>s.Id==p.Schematic);if(p.Pending.Count>0&&p.Due<=at){decimal volume=p.Pending.Sum(i=>i.Value*(decimal)ItemVolume(i.Key));if(PinVolumeQ(p)+volume<=p.Capacity){foreach(var i in p.Pending)p.Stock[i.Key]=p.Stock.GetValueOrDefault(i.Key)+i.Value;p.Pending.Clear();p.Status="Cycle complete";}else p.Status="Output blocked";}
     if(p.Pending.Count==0){if(s.Inputs.All(i=>p.Stock.GetValueOrDefault(CatalogQ.Item(i.Type))>=i.Quantity)){foreach(var i in s.Inputs)p.Stock[CatalogQ.Item(i.Type)]-=i.Quantity;p.Pending=s.Outputs.ToDictionary(i=>CatalogQ.Item(i.Type),i=>(decimal)i.Quantity);p.Due=at.AddSeconds(s.Seconds);p.Status="Processing";}else p.Status="Missing inputs";}}
   }
   foreach(var r in c.Routes){var from=c.Pins.First(p=>p.Id==r.From);var to=c.Pins.First(p=>p.Id==r.To);var link=c.Links.First(l=>l.A==r.From&&l.B==r.To||l.B==r.From&&l.A==r.To);decimal vol=(decimal)ItemVolume(r.Item);decimal q=Math.Min(from.Stock.GetValueOrDefault(r.Item),Math.Min(r.Rate/2,Math.Min(decimal.Floor((link.Capacity/2-link.Used)/vol),decimal.Floor((to.Capacity-PinVolumeQ(to))/vol))));if(q<=0)continue;from.Stock[r.Item]-=q;to.Stock[r.Item]=to.Stock.GetValueOrDefault(r.Item)+q;link.Used+=q*vol;}
  }c.Last=c.Last.AddMinutes(bounded*30);}
  BindPlanetLaunchesQ();
 }
 public string DecommissionPlanetQ(string id){var c=SystemsQ.Colonies.FirstOrDefault(c=>c.Id==id&&c.Owner=="player"&&c.Active);if(c==null)return "Owned active colony required.";c.Active=false;c.Pins.Clear();c.Links.Clear();c.Routes.Clear();LogQ("Planetary colony decommissioned; surface stock lost");return "";}
}
